"""Generated bytes and isolated data only; no user files or repair writes."""
import hashlib
import io
from pathlib import Path

import pytest
from sqlalchemy import select

from front_api import models as m
from front_api.db import new_session
from front_api.ingest import ingest, ingest_stream, index_file, ManagedFileIntegrityError


def save(payload, name='sample.bin'):
    with new_session() as session:
        asset, created = ingest(session, payload, name)
        assert created
        session.commit()
        return asset.id, asset.file_path


def assert_unchanged_staging(data_dir):
    assert not list((data_dir / '.staging').iterdir())


def test_healthy_duplicate_preserves_personal_metadata(client, data_dir):
    payload = b'generated healthy duplicate'
    aid, rel = save(payload)
    with new_session() as session:
        original = session.get(m.Asset, aid)
        original.title = 'personal title'; original.stars = 4; original.description = 'keep me'
        session.commit()
        asset, created = ingest(session, payload, 'new-name.bin', title='must not overwrite')
        assert not created and asset.id == aid
        assert (asset.title, asset.stars, asset.description) == ('personal title', 4, 'keep me')
    assert (data_dir / rel).read_bytes() == payload
    assert_unchanged_staging(data_dir)


@pytest.mark.parametrize('damage', ['same-size', 'oversized', 'missing', 'directory'])
def test_damaged_duplicate_is_refused_without_repairs(client, data_dir, damage):
    payload = b'generated original'
    aid, rel = save(payload)
    path = data_dir / rel
    if damage == 'same-size': path.write_bytes(b'x' * len(payload))
    if damage == 'oversized': path.write_bytes(payload + b'extra')
    if damage in ('missing', 'directory'): path.unlink()
    if damage == 'directory': path.mkdir()
    before = path.read_bytes() if path.is_file() else None
    with new_session() as session:
        with pytest.raises(ManagedFileIntegrityError) as error:
            ingest(session, payload, 'duplicate.bin')
        assert error.value.status_code == 409
        assert error.value.detail['damaged_asset_id'] == aid
        assert 'asset_id' not in error.value.detail
        assert str(data_dir) not in str(error.value.detail)
        assert len(session.scalars(select(m.Asset)).all()) == 1
        assert session.get(m.Asset, aid).file_path == rel
    if before is not None: assert path.read_bytes() == before
    else: assert path.is_dir() if damage == 'directory' else not path.exists()
    assert_unchanged_staging(data_dir)


def test_duplicate_upload_reports_integrity_instead_of_normal_duplicate(client, data_dir):
    payload = b'upload generated original'
    aid, rel = save(payload)
    assert client.post('/api/assets/upload', files={'file': ('sample.bin', payload)}).json()['detail']['asset_id'] == aid
    (data_dir / rel).write_bytes(b'x' * len(payload))
    response = client.post('/api/assets/upload', files={'file': ('sample.bin', payload)})
    assert response.status_code == 409
    assert response.json()['detail']['code'] == 'managed_file_hash_mismatch'
    assert response.json()['detail']['damaged_asset_id'] == aid
    assert 'asset_id' not in response.json()['detail']


def test_orphan_content_path_is_verified_before_registering(client, data_dir):
    from datetime import date
    payload = b'new generated source'; sha = hashlib.sha256(payload).hexdigest()
    dest = data_dir / 'media' / date.today().strftime('%Y/%m') / (sha + '.bin')
    dest.parent.mkdir(parents=True, exist_ok=True); dest.write_bytes(b'x' * len(payload))
    with new_session() as session:
        with pytest.raises(ManagedFileIntegrityError): ingest(session, payload, 'sample.bin')
        assert session.scalar(select(m.Asset)) is None
    assert dest.read_bytes() == b'x' * len(payload)
    dest.write_bytes(payload)
    with new_session() as session:
        asset, created = ingest(session, payload, 'sample.bin')
        assert created and asset.sha256 == sha
    assert_unchanged_staging(data_dir)


def test_external_index_does_not_adopt_broken_managed_record(client, data_dir, tmp_path):
    payload = b'index generated source'; aid, rel = save(payload)
    (data_dir / rel).unlink()
    source = tmp_path / 'external.bin'; source.write_bytes(payload)
    with new_session() as session:
        with pytest.raises(ManagedFileIntegrityError):
            index_file(session, source, tmp_path, hashlib.sha256(payload).hexdigest())
        assert session.get(m.Asset, aid).file_path == rel
        assert session.get(m.ExternalAssetFile, aid) is None
    assert source.read_bytes() == payload


def test_invalid_path_and_read_error_never_leak_private_paths(client, data_dir, tmp_path, monkeypatch):
    payload = b'generated secret path test'; aid, rel = save(payload)
    outside = tmp_path / 'private-original.bin'; outside.write_bytes(payload)
    with new_session() as session:
        asset = session.get(m.Asset, aid); asset.file_path = str(outside); session.commit()
        with pytest.raises(ManagedFileIntegrityError) as error: ingest(session, payload, 'sample.bin')
        assert str(outside) not in str(error.value.detail)
        asset.file_path = rel; session.commit()
        original = Path.open
        def denied(path, *args, **kwargs):
            if path == (data_dir / rel).resolve(): raise PermissionError('private detail must not leak')
            return original(path, *args, **kwargs)
        monkeypatch.setattr(Path, 'open', denied)
        with pytest.raises(ManagedFileIntegrityError) as error: ingest(session, payload, 'sample.bin')
        assert error.value.code == 'managed_file_unavailable'
        assert 'private detail' not in str(error.value.detail)
    assert outside.read_bytes() == payload
    assert_unchanged_staging(data_dir)


def test_streamed_duplicate_limits_each_read_and_allows_empty_file(client, data_dir, monkeypatch):
    payload = b'x' * (2 * 1024 * 1024 + 13); aid, rel = save(payload)
    reads = []; original = Path.open
    class Reader:
        def __init__(self, file): self.file = file
        def __enter__(self): self.file.__enter__(); return self
        def __exit__(self, *args): return self.file.__exit__(*args)
        def fileno(self): return self.file.fileno()
        def read(self, size=-1):
            assert 0 < size <= 1024 * 1024
            reads.append(size); return self.file.read(size)
    def tracking(path, *args, **kwargs):
        file = original(path, *args, **kwargs)
        return Reader(file) if path == (data_dir / rel).resolve() else file
    monkeypatch.setattr(Path, 'open', tracking)
    with new_session() as session:
        asset, created = ingest_stream(session, io.BytesIO(payload), 'sample.bin')
        assert asset.id == aid and not created
    assert len(reads) >= 3
    empty_id, _ = save(b'', 'empty.bin')
    with new_session() as session:
        asset, created = ingest(session, b'', 'empty.bin')
        assert asset.id == empty_id and not created
    assert_unchanged_staging(data_dir)


def test_file_changed_during_verification_is_refused(client, data_dir, monkeypatch):
    from front_api import ingest as module
    payload = b'generated race sample'; _, rel = save(payload)
    real_stat = module.os.fstat; count = 0
    def changed(fd):
        nonlocal count
        result = real_stat(fd); count += 1
        if count == 2:
            (data_dir / rel).write_bytes(payload)
            # Alter the reported descriptor signature deterministically; no timing assumption.
            class Changed:
                st_dev = result.st_dev; st_ino = result.st_ino; st_size = result.st_size
                st_mtime_ns = result.st_mtime_ns + 1; st_ctime_ns = result.st_ctime_ns
            return Changed()
        return result
    monkeypatch.setattr(module.os, 'fstat', changed)
    with new_session() as session:
        with pytest.raises(ManagedFileIntegrityError): ingest(session, payload, 'sample.bin')
    assert_unchanged_staging(data_dir)


def test_descriptor_and_path_stat_representations_need_not_match(client, data_dir, monkeypatch):
    from types import SimpleNamespace
    from front_api import ingest as module
    payload = b'generated Windows stat compatibility'; aid, _ = save(payload)
    original = module.os.fstat
    def different_representation(fd):
        value = original(fd)
        return SimpleNamespace(st_mode=value.st_mode, st_size=value.st_size,
            st_dev=value.st_dev + 1, st_ino=0,
            st_mtime_ns=(value.st_mtime_ns // 1000000000) * 1000000000,
            st_ctime_ns=(value.st_ctime_ns // 1000000000) * 1000000000)
    monkeypatch.setattr(module.os, 'fstat', different_representation)
    with new_session() as session:
        asset, created = ingest(session, payload, 'duplicate.bin')
        assert not created and asset.id == aid
    assert_unchanged_staging(data_dir)
